#include "../src/AlphaSimulation.h"
#include <iostream>
#include <fstream>
#include <stdexcept>
using namespace alpha;
int checks=0;
void check(bool value,const std::string& name){if(!value)throw std::runtime_error(name);++checks;std::cout<<"PASS "<<name<<std::endl;}
void advance(World& w,float s){for(int i=0;i<int(s*20);++i)w.step(.05f);}
int count(World& w,Kind k){int n=0;for(auto& e:w.entities)if(e.hp>0&&e.kind==k&&e.team==0)++n;return n;}
void unlock(World& w,int faction=0){w.reset(faction);w.raidsEnabled=false;w.gold=w.wood=w.oil=10000;w.townLevel[0]=3;int barracks=w.add(Kind::Barracks,0,{750,750});w.get(barracks)->level=3;for(int i=0;i<int(Research::Town4);++i)w.upgrades[0][i]=researchCatalog()[i].maxLevel;for(int i=int(Kind::Farm);i<=int(Kind::Wall);++i)if(Kind(i)!=Kind::OilRig)w.add(Kind(i),0,{150.f+(i%7)*260.f,100.f+(i/7-3)*200.f});for(int i=0;i<8;++i)w.add(Kind::Farm,0,{150.f+i*200,950});}
int main(){try{
 int unitTypes=0,structures=0;for(int i=0;i<int(Kind::CrystalCave);++i){auto k=Kind(i);check(def(k).name[0]!=0,"catalog name "+std::to_string(i));if(mobile(k))++unitTypes;else if(!resource(k))++structures;}
 check(unitTypes==19&&structures==18,"19 unit roles and 18 structures");
 for(int i=0;i<int(Kind::CrystalCave);++i){auto kind=Kind(i);if(!mobile(kind)||def(kind).producer==Kind::Count)continue;World w;unlock(w,kind==Kind::Warlock?1:0);int producer=-1;for(auto& e:w.entities)if(e.team==0&&e.kind==def(kind).producer){producer=e.id;break;}int before=count(w,kind);auto c=def(kind).cost;int gold=w.gold,wood=w.wood,oil=w.oil;
  check(w.train(producer,kind),std::string("train ")+name(kind));check(w.gold==gold-c.gold&&w.wood==wood-c.wood&&w.oil==oil-c.oil,"training pays all resource types");advance(w,def(kind).seconds+.3f);check(count(w,kind)==before+1,std::string("spawn ")+name(kind));for(auto& e:w.entities)if(e.kind==kind&&e.team==0&&e.hp>0)check(def(kind).domain==Domain::Air||w.water(e.pos)==(def(kind).domain==Domain::Sea),"unit spawns in correct movement domain");
 }
 for(int i=int(Kind::Farm);i<=int(Kind::Wall);++i){auto kind=Kind(i);World w;w.reset();w.raidsEnabled=false;w.gold=w.wood=w.oil=10000;w.townLevel[0]=3;w.upgrades[0].fill(2);for(int k=0;k<int(Kind::CrystalCave);++k)if(!mobile(Kind(k))&&!resource(Kind(k))&&Kind(k)!=kind)w.add(Kind(k),0,{100,100});
  int builder=7;sf::Vector2f p{1050,750};w.get(builder)->pos={900,750};if(kind==Kind::Shipyard){w.get(builder)->pos={700,1000};p={700,1120};}if(kind==Kind::OilRig){builder=w.add(Kind::Tanker,0,{810,1410});p={900,1410};}
  check(w.build(builder,p,kind),std::string("construct ")+name(kind));int id=w.entities.back().id;check(w.get(id)->build>0,"building initially incomplete");advance(w,def(kind).seconds+8.f);check(w.get(id)->build==0,std::string("complete ")+name(kind));
 }
 {World w;w.reset();check(!w.train(1,Kind::Archer),"wrong producer rejected");int b=w.add(Kind::Barracks,0,{750,750});w.gold=1000;check(!w.train(b,Kind::Knight),"cavalry locked by tier and stable");w.townLevel[0]=3;check(!w.train(b,Kind::Archer),"archer requires lumber mill");}
 {World w;w.reset();int cap=w.capacity(0);int f=w.add(Kind::Farm,0,{1000,750});check(w.capacity(0)==cap+6,"farm expands population");w.get(f)->hp=0;check(w.capacity(0)==cap,"destroyed farm removes capacity");}
 for(int i=0;i<int(Research::Town4);++i){World w;unlock(w);auto tech=Research(i);w.upgrades[0][i]=0;int building=-1;for(auto& b:w.entities)if(b.team==0&&b.kind==researchCatalog()[i].building){building=b.id;break;}if(tech==Research::Town2)w.townLevel[0]=1;if(tech==Research::Town3)w.townLevel[0]=2;if(tech==Research::Barracks2)w.get(building)->level=1;if(tech==Research::Barracks3)w.get(building)->level=2;check(w.research(building,tech),"research starts "+std::to_string(i));advance(w,researchCatalog()[i].seconds+.2f);check(w.upgrades[0][i]==1,"research completes "+std::to_string(i));}
 {World w;unlock(w);int tower=w.add(Kind::WatchTower,0,{900,750});check(w.upgradeTower(tower,Kind::GuardTower),"watchtower upgrade starts");advance(w,8.2f);check(w.get(tower)->kind==Kind::GuardTower,"watchtower transforms into guard tower");}
 {World w;unlock(w);int port=-1;for(auto& e:w.entities)if(e.kind==Kind::Shipyard&&e.team==0)port=e.id;int gold=w.gold,wood=w.wood,oil=w.oil;check(w.train(port,Kind::Battleship),"naval production starts");check(w.cancel(port),"production cancels");check(w.gold==gold&&w.wood==wood&&w.oil==oil,"cancellation refunds exact paid resources");}
 {World w;w.reset();auto worker=w.get(7);check(!w.path(*worker,{500,1400}),"land cannot path into sea");int boat=w.add(Kind::Tanker,0,{600,1380});check(!w.path(*w.get(boat),{600,900}),"ship cannot path onto land");int air=w.add(Kind::Scout,0,{700,700});check(w.path(*w.get(air),{700,1450}),"air unit crosses coastline");}
 {World w;w.reset();w.raidsEnabled=false;int archer=w.add(Kind::Archer,0,{800,700}),enemy=w.add(Kind::Soldier,1,{1050,700});float before=w.get(enemy)->hp;w.attack(*w.get(archer),enemy);w.step(.05f);check(!w.shots.empty()&&w.get(enemy)->hp==before,"ranged attack launches travelling projectile");advance(w,1);check(w.get(enemy)->hp<before,"projectile applies damage after travel");}
 {World w;w.reset();int flyer=w.add(Kind::Scout,1,{1000,700});check(!w.canHit(*w.get(11),*w.get(flyer)),"melee cannot hit air");int archer=w.add(Kind::Archer,0,{800,700});check(w.canHit(*w.get(archer),*w.get(flyer)),"archer can hit air");int sub=w.add(Kind::Submarine,1,{1000,1400});int battleship=w.add(Kind::Battleship,0,{800,1400});check(!w.canHit(*w.get(battleship),*w.get(sub)),"submarine hidden without detector");w.add(Kind::Destroyer,0,{850,1400});check(w.canHit(*w.get(battleship),*w.get(sub)),"destroyer detects submarine");}
 {World w;w.reset();w.raidsEnabled=false;int ship=w.add(Kind::Transport,0,{600,1280});w.get(7)->pos={600,1140};w.board(*w.get(7),ship);advance(w,3);check(w.get(7)->carrier==ship,"land unit boards transport");check(w.unload(ship,{600,1140}),"transport unloads near land");check(w.get(7)->carrier==-1&&!w.water(w.get(7)->pos),"unloaded unit placed on land");}
 {World w;w.reset();w.raidsEnabled=false;w.gold=w.wood=1000;w.add(Kind::Shipyard,0,{700,1120});int tanker=w.add(Kind::Tanker,0,{810,1410});check(w.build(tanker,{900,1410},Kind::OilRig),"tanker builds oil platform on deposit");int rig=w.entities.back().id;advance(w,12.2f);w.gather(*w.get(tanker),rig);advance(w,35);check(w.oil>0,"tanker collects and deposits oil at shipyard");}
 {World w;w.reset();w.raidsEnabled=false;w.get(1)->hp-=100;w.get(7)->pos={380,750};w.repair(*w.get(7),1);float before=w.get(1)->hp;advance(w,3);check(w.get(1)->hp>before,"worker repairs allied building");}
 {World w;w.reset();w.raidsEnabled=false;int healer=w.add(Kind::Healer,0,{800,750});w.get(11)->hp-=70;float before=w.get(11)->hp;check(w.cast(healer,Spell::Heal,w.get(11)->pos),"manual healing spell");check(w.get(11)->hp>before&&w.get(healer)->mana==95,"healing restores health and consumes mana");check(!w.cast(healer,Spell::Heal,w.get(11)->pos),"spell cooldown enforced");}
 {World w;w.reset();w.raidsEnabled=false;w.upgrades[0][int(Research::Arcana)]=1;int mage=w.add(Kind::Mage,0,{800,750}),enemy=w.add(Kind::Soldier,1,{1000,750});float before=w.get(enemy)->hp;check(w.cast(mage,Spell::Firestorm,{1000,750}),"area damage spell");check(w.get(enemy)->hp<before,"spell damages enemies");}
 {World w;w.reset(1);w.raidsEnabled=false;w.upgrades[0][int(Research::Arcana)]=1;int caster=w.add(Kind::Warlock,0,{800,750}),dead=w.add(Kind::Soldier,1,{900,750});w.get(dead)->hp=0;check(w.cast(caster,Spell::Raise,{900,750}),"summoning uses a corpse");check(count(w,Kind::Spirit)==1,"spirit summoned");advance(w,46);check(count(w,Kind::Spirit)==0,"summoned unit expires");}
 for(int f=0;f<2;++f){World w;w.reset(f);w.prepareArsenal();check(w.townLevel[0]==3&&!w.raidsEnabled&&w.gold==8000,"arsenal preset faction "+std::to_string(f));for(int k=0;k<int(Kind::CrystalCave);++k)if(mobile(Kind(k))&&def(Kind(k)).producer!=Kind::Count&&w.unavailable(Kind(k)).empty())check(count(w,Kind(k))>0,"arsenal contains "+std::string(name(Kind(k))));}
 std::ofstream table("catalogo-contenuti.tsv");table<<"tipo\tnome\tclan\toro\tlegno\tpetrolio\ttempo\tlivello\tproduttore\tprerequisito\n";for(int i=0;i<int(Kind::CrystalCave);++i){auto k=Kind(i);auto& d=def(k);table<<(mobile(k)?"unita":(resource(k)?"risorsa":"edificio"))<<'\t'<<d.name<<'\t'<<d.clanName<<'\t'<<d.cost.gold<<'\t'<<d.cost.wood<<'\t'<<d.cost.oil<<'\t'<<d.seconds<<'\t'<<d.tier<<'\t'<<name(d.producer)<<'\t'<<name(d.prerequisite)<<'\n';}
 std::cout<<"SUCCESS "<<checks<<" roster checks"<<std::endl;return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}



